func init() {
	for _, entry := range pluginmanagerLocaleCatalog {
		i18n.Register("pluginmanager"+"."+entry.module+"."+entry.key, entry.zh, entry.en)
	}
}

func pluginManagerLocaleText(key string) string {
	zh := i18n.Locale() == i18n.LocaleZH
	for _, entry := range pluginmanagerLocaleCatalog {
		if entry.key == key || entry.module+"."+entry.key == key {
			if zh {
				return entry.zh
			}
			return entry.en
		}
	}
	return i18n.T(key)
}
